const puppeteer = require("puppeteer-core");   // NOT "puppeteer" — it downloads its own Chrome

if (!process.env.ANNA_CHROME_EXECUTABLE) {
  throw new Error("platform Chrome missing — declare runtime.requires.chrome in executa.json");
}
console.error("platform chrome", process.env.ANNA_CHROME_VERSION); // stderr: stdout is the protocol channel

const browser = await puppeteer.launch({
  executablePath: process.env.ANNA_CHROME_EXECUTABLE,
  headless: true,
  args: ["--no-sandbox", "--disable-dev-shm-usage"], // required on Cloud Agents
});

#!/bin/sh
# bin/ppt-engine — lightweight entrypoint, no embedded Node
set -eu
: "${ANNA_NODE_EXECUTABLE:?This Executa requires the Anna platform Node.js runtime. Declare runtime.requires.node in executa.json and install on an up-to-date Agent.}"
exec "$ANNA_NODE_EXECUTABLE" --enable-source-maps "$EXECUTA_HOME/dist/main.js" "$@"

:: bin/ppt-engine.cmd — Windows
@echo off
if "%ANNA_NODE_EXECUTABLE%"=="" (echo ANNA_NODE_EXECUTABLE missing 1>&2 & exit /b 2)
"%ANNA_NODE_EXECUTABLE%" "%EXECUTA_HOME%\dist\main.js" %*

const runtimes = process.env.ANNA_RUNTIMES_JSON
  ? JSON.parse(process.env.ANNA_RUNTIMES_JSON)
  : null;

if (!runtimes) {
  // Agent predates the contract: degrade gracefully (e.g. scan PLAYWRIGHT_BROWSERS_PATH)
  // or declare runtime.requires so the install fails loudly instead.
}
console.error("profile", runtimes?.profile, "agent", process.env.ANNA_AGENT_VERSION);

